#!/usr/bin/env python3\n\"\"\"\nQuick Start Test Script\n======================\nRun the adaptive trading system with minimal setup for immediate testing.\n\"\"\"\n\nimport os\nimport sys\nimport logging\nfrom datetime import datetime\n\n# Setup basic logging\nlogging.basicConfig(\n    level=logging.INFO,\n    format='%(asctime)s | %(levelname)s | %(message)s'\n)\nlogger = logging.getLogger(__name__)\n\ndef check_dependencies():\n    \"\"\"Check if required packages are installed\"\"\"\n    required_packages = {\n        'pandas': 'pandas',\n        'numpy': 'numpy', \n        'yfinance': 'yfinance',\n        'scipy': 'scipy'\n    }\n    \n    missing = []\n    for package, import_name in required_packages.items():\n        try:\n            __import__(import_name)\n            logger.info(f\"✅ {package} - OK\")\n        except ImportError:\n            logger.error(f\"❌ {package} - MISSING\")\n            missing.append(package)\n    \n    return missing\n\ndef install_missing_packages(packages):\n    \"\"\"Install missing packages\"\"\"\n    if not packages:\n        return\n    \n    logger.info(f\"Installing missing packages: {', '.join(packages)}\")\n    \n    import subprocess\n    for package in packages:\n        try:\n            subprocess.check_call([sys.executable, \"-m\", \"pip\", \"install\", package])\n            logger.info(f\"✅ Installed {package}\")\n        except subprocess.CalledProcessError as e:\n            logger.error(f\"❌ Failed to install {package}: {e}\")\n\ndef run_quick_test():\n    \"\"\"Run a quick 5-minute test\"\"\"\n    logger.info(\"🚀 Starting Quick Adaptive Trading Test\")\n    logger.info(\"📋 Test Configuration:\")\n    logger.info(\"   • Mode: Paper Trading\")\n    logger.info(\"   • Duration: 5 minutes\")\n    logger.info(\"   • Symbols: RELIANCE.NS, TCS.NS, HDFCBANK.NS\")\n    logger.info(\"   • Update Interval: 1 minute\")\n    logger.info(\"\")\n    \n    try:\n        # Add src to path\n        sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'src'))\n        \n        # Import our test module\n        from test_adaptive_live import AdaptiveTradingTest\n        \n        # Create test with limited symbols and short duration\n        test = AdaptiveTradingTest(\n            mode=\"paper\", \n            symbols=[\"RELIANCE.NS\", \"TCS.NS\", \"HDFCBANK.NS\"]\n        )\n        \n        # Run 5-minute test\n        test.run_test_cycle(duration_minutes=5)\n        \n    except ImportError as e:\n        logger.error(f\"❌ Import Error: {e}\")\n        logger.error(\"   Make sure all required files are in place\")\n    except Exception as e:\n        logger.error(f\"❌ Test Error: {e}\")\n        logger.error(\"   Check logs for detailed error information\")\n\ndef main():\n    \"\"\"Main function\"\"\"\n    print(\"🔧 Adaptive Trading System - Quick Start\")\n    print(\"==========================================\\n\")\n    \n    # Check dependencies\n    print(\"📦 Checking Dependencies...\")\n    missing = check_dependencies()\n    \n    if missing:\n        print(f\"\\n❌ Missing packages: {', '.join(missing)}\")\n        response = input(\"\\n🤔 Install missing packages automatically? (y/n): \")\n        if response.lower() == 'y':\n            install_missing_packages(missing)\n        else:\n            print(\"\\n⚠️ Please install missing packages manually:\")\n            for package in missing:\n                print(f\"   pip install {package}\")\n            return\n    \n    print(\"\\n✅ All dependencies satisfied!\\n\")\n    \n    # Ask user if they want to run test\n    response = input(\"🤔 Run 5-minute adaptive trading test? (y/n): \")\n    if response.lower() == 'y':\n        run_quick_test()\n    else:\n        print(\"\\n📖 To run tests later, use:\")\n        print(\"   python test_adaptive_live.py --duration 30\")\n        print(\"   python test_adaptive_live.py --symbols RELIANCE.NS,TCS.NS --duration 60\")\n\nif __name__ == \"__main__\":\n    main()"